SET ROLE talus_fn;
CREATE OR REPLACE FUNCTION app.append_audit(p_action text,p_resource_type text,p_resource_id uuid,p_operation_id uuid DEFAULT NULL,p_details jsonb DEFAULT '{}'::jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE v_event uuid;v_prev text;v_at timestamptz:=clock_timestamp();v_hash text;BEGIN PERFORM app.require_context();PERFORM pg_advisory_xact_lock(hashtextextended(app.current_context_tenant_id()::text,0));SELECT event_hash INTO v_prev FROM app.audit_event WHERE tenant_id=app.current_context_tenant_id() AND event_hash IS NOT NULL ORDER BY occurred_at DESC,audit_event_id DESC LIMIT 1;v_prev:=COALESCE(v_prev,repeat('0',64));v_hash:=encode(public.digest(v_prev||app.current_context_tenant_id()::text||p_action||COALESCE(app.current_context_principal_id()::text,'')||p_details::text||v_at::text,'sha256'),'hex');INSERT INTO app.audit_event(tenant_id,actor_principal_id,action,resource_type,resource_id,operation_id,details,occurred_at,previous_event_hash,event_hash) VALUES(app.current_context_tenant_id(),app.current_context_principal_id(),p_action,p_resource_type,p_resource_id,p_operation_id,p_details,v_at,v_prev,v_hash) RETURNING audit_event_id INTO v_event;RETURN v_event;END;$$;
RESET ROLE;
